test('reduce a confirmed order of 2', async () => {
  const h = await fresh();
  await h.restock();
  await h.place('a', 2);
  assert.equal((await h.reduce('a')).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.reduce('a'), { ok: true });
  assert.deepEqual(await h.order('a'), { status: 'confirmed', qty: 1 });
  const m = await h.inFlight();
  assert.deepEqual([m[0].from, m[0].to, m[0].action, m[0].data], ['a', 'inventory', 'Release', { qty: 1 }]);
  await h.deliverAll();
  assert.deepEqual(await h.stock(), { available: 1, reserved: 1, open: true });
  assert.equal((await h.reduce('a')).ok, false);
  await h.cancel('a');
  await h.deliverAll();
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0, open: true });
  assert.equal((await h.reduce('a')).ok, false);
  assert.equal((await h.reduce('nope')).ok, false);
});

test('reduce then expire, releases in any order', async () => {
  const h = await fresh();
  await h.restock();
  await h.place('a', 2);
  await h.deliverAll();
  await h.reduce('a');
  await h.expire('a');
  const m = await h.inFlight();
  assert.equal(m.length, 2);
  await h.deliver(m[1].id);
  await h.deliver(m[0].id);
  assert.deepEqual(await h.order('a'), { status: 'expired', qty: 1 });
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0, open: true });
});

