import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const fresh = async () => (await createHost()) as any;

test('initial state', async () => {
  const h = await fresh();
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: true });
  assert.equal(await h.order('a'), null);
  assert.deepEqual(await h.inFlight(), []);
});

test('place, reserve, confirm', async () => {
  const h = await fresh();
  assert.deepEqual(await h.place('a', 1), { ok: true });
  assert.deepEqual(await h.order('a'), { status: 'pending', qty: 1 });
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 1);
  assert.equal(msgs[0].from, 'a');
  assert.equal(msgs[0].to, 'inventory');
  assert.equal(msgs[0].action, 'Reserve');
  assert.deepEqual(msgs[0].data, { from: 'a', qty: 1 });
  await h.deliver(msgs[0].id);
  const reply = await h.inFlight();
  assert.equal(reply.length, 1);
  assert.deepEqual([reply[0].from, reply[0].to, reply[0].action, reply[0].data], ['inventory', 'a', 'Reserved', {}]);
  assert.deepEqual(await h.stock(), { available: 0, reserved: 1, open: true });
  await h.deliverAll();
  assert.deepEqual(await h.order('a'), { status: 'confirmed', qty: 1 });
});

test('refusals', async () => {
  const h = await fresh();
  for (const q of [0, 3, 1.5]) {
    const r = await h.place('a', q);
    assert.equal(r.ok, false);
    assert.equal(await h.order('a'), null);
  }
  assert.deepEqual(await h.inFlight(), []);
  assert.equal((await h.cancel('nope')).ok, false);
  assert.equal(await h.order('nope'), null);
  assert.deepEqual(await h.place('a', 2), { ok: true });
  assert.equal((await h.place('a', 1)).ok, false);
  assert.deepEqual(await h.order('a'), { status: 'pending', qty: 2 });
  assert.equal((await h.inFlight()).length, 1);
});

test('out of stock rejects', async () => {
  const h = await fresh();
  await h.place('a', 2);
  await h.deliverAll();
  assert.deepEqual(await h.order('a'), { status: 'rejected', qty: 2 });
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: true });
  assert.equal((await h.cancel('a')).ok, false);
});

test('restock up to 3', async () => {
  const h = await fresh();
  assert.deepEqual(await h.restock(), { ok: true });
  assert.deepEqual(await h.restock(), { ok: true });
  assert.equal((await h.restock()).ok, false);
  assert.deepEqual(await h.stock(), { available: 3, reserved: 0, open: true });
  await h.place('a', 2);
  await h.deliverAll();
  assert.equal((await h.restock()).ok, false);
  assert.deepEqual(await h.stock(), { available: 1, reserved: 2, open: true });
});

test('cancel confirmed releases', async () => {
  const h = await fresh();
  await h.place('a', 1);
  await h.deliverAll();
  assert.deepEqual(await h.cancel('a'), { ok: true });
  assert.deepEqual(await h.order('a'), { status: 'cancelled', qty: 1 });
  const m = await h.inFlight();
  assert.deepEqual([m[0].action, m[0].data], ['Release', { qty: 1 }]);
  await h.deliverAll();
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: true });
  assert.equal((await h.cancel('a')).ok, false);
});

test('cancel pending, then reserved: gives back', async () => {
  const h = await fresh();
  await h.place('a', 1);
  assert.deepEqual(await h.cancel('a'), { ok: true });
  assert.deepEqual(await h.order('a'), { status: 'cancelling', qty: 1 });
  assert.equal((await h.cancel('a')).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.order('a'), { status: 'cancelled', qty: 1 });
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: true });
});

test('cancel pending, then out of stock', async () => {
  const h = await fresh();
  await h.place('a', 2);
  await h.cancel('a');
  await h.deliverAll();
  assert.deepEqual(await h.order('a'), { status: 'cancelled', qty: 2 });
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: true });
});

test('expire a confirmed order releases', async () => {
  const h = await fresh();
  await h.place('a', 1);
  await h.deliverAll();
  assert.deepEqual(await h.expire('a'), { ok: true });
  assert.deepEqual(await h.order('a'), { status: 'expired', qty: 1 });
  const m = await h.inFlight();
  assert.deepEqual([m[0].from, m[0].to, m[0].action, m[0].data], ['a', 'inventory', 'Release', { qty: 1 }]);
  await h.deliverAll();
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: true });
  assert.equal((await h.expire('a')).ok, false);
  assert.equal((await h.cancel('a')).ok, false);
  assert.equal((await h.place('a', 1)).ok, false);
  assert.deepEqual(await h.order('a'), { status: 'expired', qty: 1 });
});

test('expire refused unless confirmed', async () => {
  const h = await fresh();
  assert.equal((await h.expire('nope')).ok, false);
  await h.place('a', 1);
  assert.equal((await h.expire('a')).ok, false);
  await h.cancel('a');
  assert.equal((await h.expire('a')).ok, false);
  await h.deliverAll();
  assert.equal((await h.expire('a')).ok, false);
  await h.place('b', 2);
  await h.deliverAll();
  assert.equal((await h.expire('b')).ok, false);
  assert.equal((await h.order('b')).status, 'rejected');
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: true });
});

test('close and open', async () => {
  const h = await fresh();
  assert.equal((await h.open()).ok, false);
  assert.deepEqual(await h.close(), { ok: true });
  assert.equal((await h.close()).ok, false);
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: false });
  assert.equal((await h.restock()).ok, false);
  await h.place('a', 1);
  await h.deliverAll();
  assert.equal((await h.order('a')).status, 'rejected');
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: false });
  assert.deepEqual(await h.open(), { ok: true });
  assert.deepEqual(await h.restock(), { ok: true });
  await h.place('b', 2);
  await h.deliverAll();
  assert.equal((await h.order('b')).status, 'confirmed');
  assert.deepEqual(await h.stock(), { available: 0, reserved: 2, open: true });
});

test('release is taken while closed', async () => {
  const h = await fresh();
  await h.place('a', 1);
  await h.deliverAll();
  await h.close();
  await h.cancel('a');
  await h.deliverAll();
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: false });
});

test('closed between reserve sent and delivered', async () => {
  const h = await fresh();
  await h.place('a', 1);
  await h.close();
  await h.deliverAll();
  assert.equal((await h.order('a')).status, 'rejected');
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: false });
});

test('two orders race for one unit', async () => {
  const h = await fresh();
  await h.place('a', 1);
  await h.place('b', 1);
  const msgs = await h.inFlight();
  const b = msgs.find((m: any) => m.from === 'b');
  await h.deliver(b.id);
  await h.deliverAll();
  assert.equal((await h.order('a')).status, 'rejected');
  assert.equal((await h.order('b')).status, 'confirmed');
  assert.deepEqual(await h.stock(), { available: 0, reserved: 1, open: true });
});
